const BHOJPURI_STATS=[{label:"Speakers Worldwide",value:"~50 Million"},{label:"Language Family",value:"Indo-Aryan"},{label:"Script",value:"Devanagari"},{label:"Primary Region",value:"East UP & West Bihar"}],BHOJPURI_GREETING={devanagari:"प्रणाम",transliteration:"Praṇām",meaning:"The standard respectful greeting used across the Bhojpuri-speaking region, for both hello and goodbye, especially toward elders — shared broadly with Hindi and neighboring Gangetic-plain languages.",folkVariant:{devanagari:"राम राम",transliteration:"Rām Rām",meaning:"An extremely common, warm everyday greeting used throughout the Bhojpuri belt in both casual and respectful contexts, regardless of the speaker's religion."},note:"Bhojpuri does not have a dedicated browser text-to-speech voice, so pronunciation below plays using the closest available Hindi (Devanagari-script) voice as an approximation — not a native Bhojpuri recording. Actual Bhojpuri speech carries its own distinct rhythm and vowel sounds."},BHOJPURI_WORDS=[{devanagari:"पानी",translit:"Pānī",meaning:"Water",note:"Shared Indo-Aryan root with Hindi, pronounced with characteristic Bhojpuri vowel softening."},{devanagari:"बढ़िया",translit:"Baṛhiyā",meaning:"Good / Great",note:"One of the most recognizable everyday Bhojpuri words for expressing approval, widely known even outside the region through Bhojpuri cinema and music."},{devanagari:"घर",translit:"Ghar",meaning:"House / Home",note:"Common Indo-Aryan vocabulary shared across most Gangetic-plain languages."},{devanagari:"माई",translit:"Māī",meaning:"Mother",note:"A warm, widely used term for mother across the Bhojpuri region, distinct in form from standard Hindi 'maa'."},{devanagari:"बाबूजी",translit:"Bābūjī",meaning:"Father",note:"A respectful term for father, commonly used across Bhojpuri-speaking families."},{devanagari:"कईसे",translit:"Kaīse",meaning:"How",note:"The Bhojpuri form of Hindi 'kaise', showing the region's characteristic vowel patterns."},{devanagari:"खाना",translit:"Khānā",meaning:"Food / To eat",note:"Shared root with Hindi and other Indo-Aryan languages of the region."},{devanagari:"दिन",translit:"Din",meaning:"Day",note:"Common Indo-Aryan vocabulary tracing back to Sanskrit 'dina'."},{devanagari:"रउआ",translit:"Raüā",meaning:"You (respectful)",note:"A distinctly Bhojpuri respectful second-person pronoun, differing structurally from standard Hindi 'aap'."},{devanagari:"जल्दी",translit:"Jaldī",meaning:"Quickly",note:"Shared across neighboring Indo-Aryan languages, used identically in everyday Bhojpuri speech."}],BHOJPURI_SCRIPT={intro:"Bhojpuri is written in the Devanagari script today, the same script used for Hindi and Sanskrit, which has made its film subtitles, song lyrics, and printed literature widely accessible across the Hindi-speaking belt.",facts:[{title:"Devanagari Standard",detail:"Modern Bhojpuri books, film credits, and lyric sheets are printed in standard Devanagari, aiding mutual readability with Hindi audiences."},{title:"Kaithi Historical Use",detail:"Like several other Bihari languages, Bhojpuri was historically also written in the Kaithi script before Devanagari became the dominant standard in the 20th century."},{title:"Regional Variation",detail:"Bhojpuri varies across its Eastern UP (Purvanchal), Western Bihar, and diaspora forms, each carrying distinct vocabulary shaped by local contact and migration history."}]},BHOJPURI_CLASSIFICATION={family:"Indo-European → Indo-Iranian → Indo-Aryan → Eastern Zone (Bihari languages)",siblings:["Magahi","Maithili","Angika"],note:"Bhojpuri belongs to the Eastern Indo-Aryan 'Bihari languages' group, descending from Magadhi Prakrit and Apabhramsha, sharing deep structural roots with Magahi and Maithili while developing its own distinctive verb forms and vocabulary."},BHOJPURI_REGION={intro:"Bhojpuri is spoken across a wide belt spanning eastern Uttar Pradesh and western Bihar, and — due to 19th and 20th century indentured labor migration — carries one of the largest global diaspora footprints of any Indian regional language.",areas:["Varanasi (UP)","Ghazipur (UP)","Deoria (UP)","Gorakhpur (UP)","Ballia (UP)","Bhojpur (Bihar)","Buxar (Bihar)","Siwan (Bihar)","Mauritius (diaspora)","Fiji (diaspora)","Trinidad & Guyana (diaspora)"]},BHOJPURI_HERITAGE=[{title:"Bhojpuri Folk Music",desc:"Bhojpuri boasts one of North India's richest folk music traditions — including Chaita, Kajari (monsoon songs), Sohar (birth songs), and Bidesia performance songs historically tied to the pain of labor migration."},{title:"Bhojpuri Cinema",desc:"One of India's largest regional-language film industries, Bhojpuri cinema produces hundreds of films annually and has been central to keeping the language culturally visible across generations."},{title:"Bidesia Folk Theatre",desc:"Pioneered by poet-performer Bhikhari Thakur in the early 20th century, Bidesia is a folk theatre tradition dramatizing the hardships of migrant labor and separated families, considered a landmark of Bhojpuri performing arts."},{title:"Global Indentured Labor Diaspora",desc:"Bhojpuri speakers were among the largest groups taken as indentured laborers to Mauritius, Fiji, Trinidad, Guyana, and Suriname in the 19th century, carrying the language and its folk traditions across the world, where it survives today often blended with local Creole influences."}],BHOJPURI_REFERENCES=[{text:"Grierson, George A. Linguistic Survey of India, Vol. V: Bihari and Oriya Languages. 1903.",url:"https://archive.org/"},{text:"Tiwari, Udai Narain. The Origin and Development of Bhojpuri. Asiatic Society, 1960.",url:"https://www.jstor.org/"},{text:"Census of India — Statement of Language and Mother Tongue Strength.",url:"https://censusindia.gov.in/"},{text:"People's Linguistic Survey of India (PLSI) — Bhojpuri Volume.",url:"https://peopleslinguisticsurvey.org/"}];